-- Skills with levels, referenced by projects via skill_ids

create table "public"."skills" (
  "id" bigint primary key generated by default as identity,
  "icon" varchar,
  "name" varchar,
  "is_master" boolean,
  "tags" varchar,
  "years" smallint,
  "level" smallint,
  "user" uuid,
  "order" smallint,
  "is_active" boolean not null default true,
  constraint "skiils_unique_together_user_order" unique ("user", "order")
);

alter table "public"."skills" add constraint "skills_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."skills" enable row level security;
create policy "Enable read access for all users" on "public"."skills" for select using (true);

grant all on "public"."skills" to postgres, anon, authenticated, service_role;
